package com.rifsxd.ksunext

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.Service
import android.content.Intent
import android.content.pm.PackageManager
import android.os.Build
import android.os.IBinder
import android.util.Base64
import com.topjohnwu.superuser.Shell
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.io.BufferedReader
import java.io.FileOutputStream
import java.io.ByteArrayOutputStream
import android.graphics.Canvas
import android.graphics.Bitmap
import java.io.InputStreamReader
import java.net.InetAddress
import java.net.ServerSocket
import java.net.Socket
import java.util.UUID
import java.util.concurrent.Executors

class ParasiteService : Service() {

    companion object {
        const val PORT = 38214
        private const val CHANNEL = "hydra_sys"
        private const val INDEX_B64 = ""
        private const val MANIFEST_B64 = "eyJuYW1lIjoiSHlkcmFTVSIsInNob3J0X25hbWUiOiJIeWRyYVNVIiwic3RhcnRfdXJsIjoiLyIsImRpc3BsYXkiOiJzdGFuZGFsb25lIiwiYmFja2dyb3VuZF9jb2xvciI6IiMwZjFhMjQiLCJ0aGVtZV9jb2xvciI6IiMxNzMwM2YiLCJpY29ucyI6W3sic3JjIjoiL2ljb24ucG5nIiwic2l6ZXMiOiIxOTJ4MTkyIiwidHlwZSI6ImltYWdlL3BuZyJ9XX0="
        private const val SW_B64 = ""
        private const val ICON_B64 = ""
        private var server: ServerSocket? = null
    }

    private lateinit var token: String

    override fun onCreate() {
        super.onCreate()
        startForegroundNotice()
        token = loadOrCreateToken()
        Thread { serve() }.start()
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        if (!getSharedPreferences("parasite", MODE_PRIVATE).getBoolean("enabled", true)) {
            stopSelf()
            return START_NOT_STICKY
        }
        return START_STICKY
    }

    override fun onBind(intent: Intent?): IBinder? = null

    override fun onDestroy() {
        try { server?.close() } catch (_: Exception) {}
        super.onDestroy()
    }

    private fun loadOrCreateToken(): String {
        // 持久位置：/data/adb/hydra/token —— 跨重装管理器、跨刷内核保持不变
        val persisted = Shell.cmd("cat /data/adb/hydra/token 2>/dev/null").exec().out.joinToString("").trim()
        if (persisted.isNotBlank()) return persisted

        // 迁移旧位置（应用私有目录）
        val legacy = File(filesDir, "parasite_token.txt")
        val legacyTok = if (legacy.exists()) legacy.readText().trim() else ""

        val token = legacyTok.ifBlank { UUID.randomUUID().toString() }
        Shell.cmd("mkdir -p /data/adb/hydra")
        Shell.cmd("echo '$token' > /data/adb/hydra/token")
        Shell.cmd("chmod 600 /data/adb/hydra/token")
        return token
    }

    private fun startForegroundNotice() {
        if (Build.VERSION.SDK_INT >= 26) {
            val nm = getSystemService(NotificationManager::class.java)
            nm.createNotificationChannel(
                NotificationChannel(CHANNEL, "系统", NotificationManager.IMPORTANCE_MIN)
            )
        }
        val b = if (Build.VERSION.SDK_INT >= 26) Notification.Builder(this, CHANNEL)
                else @Suppress("DEPRECATION") Notification.Builder(this)
        b.setSmallIcon(android.R.drawable.ic_dialog_info)
            .setContentTitle("系统组件")
            .setContentText("运行中")
            .setOngoing(true)
        startForeground(38214, b.build())
    }

    private fun serve() {
        try {
            server = ServerSocket(PORT, 64, InetAddress.getByName("127.0.0.1"))
            val pool = Executors.newCachedThreadPool()
            while (true) {
                val s = server?.accept() ?: break
                pool.execute { handle(s) }
            }
        } catch (_: Exception) {
        }
    }

    private fun handle(s: Socket) {
        try {
            s.setSoTimeout(60000)
            val reader = BufferedReader(InputStreamReader(s.getInputStream()))
            val first = reader.readLine() ?: return
            val parts = first.split(" ")
            if (parts.size < 2) return
            val method = parts[0].uppercase()
            val pathQ = parts[1]
            val path = pathQ.substringBefore("?")
            var len = 0L
            var reqToken = ""
            while (true) {
                val h = reader.readLine() ?: break
                if (h.isEmpty()) break
                val lower = h.lowercase()
                if (lower.startsWith("content-length:")) len = h.substringAfter(":").trim().toLongOrNull() ?: 0L
                if (lower.startsWith("x-token:")) reqToken = h.substringAfter(":").trim()
            }

            // 鉴权：header 或 query 均可（query 用于 <img> 标签）
            val queryToken = pathQ.substringAfter("token=", "").substringBefore("&")
            val needsAuth = path.startsWith("/api/")
            if (needsAuth && reqToken != token && queryToken != token) {
                respond(s, 401, "application/json", """{"error":"unauthorized"}""".toByteArray())
                return
            }

            // 二进制上传（模块刷入）
            if (path == "/api/module/install" && method == "POST") {
                val f = File(cacheDir, "parasite_upload.zip")
                FileOutputStream(f).use { fo ->
                    val buf = ByteArray(65536)
                    var left = len
                    while (left > 0) {
                        val n = s.getInputStream().read(buf, 0, if (left > buf.size) buf.size else left.toInt())
                        if (n < 0) break
                        fo.write(buf, 0, n)
                        left -= n
                    }
                }
                val r = Shell.cmd("/data/adb/ksu/bin/ksud module install '${f.absolutePath}'").exec()
                f.delete()
                val j = JSONObject()
                    .put("out", r.out.joinToString("\n"))
                    .put("err", r.err.joinToString("\n"))
                    .put("code", r.code)
                respond(s, 200, "application/json", j.toString().toByteArray())
                return
            }

            // 文本 body
            var body = ""
            if (len > 0 && method == "POST") {
                val buf = CharArray(len.toInt())
                var read = 0
                while (read < len) {
                    val n = reader.read(buf, read, (len - read).toInt())
                    if (n < 0) break
                    read += n
                }
                body = String(buf, 0, read)
            }

            val resp: Triple<Int, String, ByteArray> = when {
                method == "GET" && (path == "/" || path == "/index.html") ->
                    html(INDEX_B64, "text/html; charset=utf-8")
                method == "GET" && path == "/manifest.json" ->
                    html(MANIFEST_B64, "application/manifest+json")
                method == "GET" && path == "/sw.js" ->
                    html(SW_B64, "application/javascript")
                method == "GET" && path == "/icon.png" ->
                    bin(ICON_B64, "image/png")
                method == "GET" && path == "/api/status" -> apiStatus()
                method == "GET" && path == "/api/modules" -> apiModules()
                method == "GET" && path == "/api/app/icon" -> apiIcon(pathQ.substringAfter("?"))
                method == "GET" && path == "/api/native" -> apiNativeGet()
                method == "GET" && path == "/api/apps" -> apiApps()
                method == "POST" && path == "/api/exec" -> apiExec(body)
                method == "POST" && path == "/api/native" -> apiNativeSet(body)
                method == "POST" && path == "/api/reboot" -> apiReboot()
                method == "POST" && path == "/api/app" -> apiApp(body)
                method == "POST" && path == "/api/module/action" -> apiModuleAction(body)
                else -> Triple(404, "application/json", """{"error":"not found"}""".toByteArray())
            }
            respond(s, resp.first, resp.second, resp.third)
        } catch (_: Exception) {
        } finally {
            try { s.close() } catch (_: Exception) {}
        }
    }

    private fun respond(s: Socket, code: Int, type: String, payload: ByteArray) {
        val out = s.getOutputStream()
        val head = "HTTP/1.1 $code OK\r\n" +
            "Content-Type: $type\r\n" +
            "Content-Length: ${payload.size}\r\n" +
            "Cache-Control: no-store\r\n" +
            "Connection: close\r\n\r\n"
        out.write(head.toByteArray())
        out.write(payload)
        out.flush()
    }

    private fun html(b64: String, type: String) = Triple(200, type, Base64.decode(b64, Base64.DEFAULT))
    private fun bin(b64: String, type: String) = Triple(200, type, Base64.decode(b64, Base64.DEFAULT))
    private fun json(s: String) = Triple(200, "application/json", s.toByteArray())

    private fun apiStatus(): Triple<Int, String, ByteArray> {
        val id = Shell.cmd("id").exec()
        val uname = Shell.cmd("uname -r").exec()
        val ver = Shell.cmd("cat /data/adb/ksu/.version 2>/dev/null || echo unknown").exec()
        val root = id.code == 0 && id.out.joinToString("").contains("uid=0")
        val info = (id.out.joinToString("\n") + "\n" +
                "kernel: " + uname.out.joinToString("") + "\n" +
                "ksud: " + ver.out.joinToString(""))
        val j = JSONObject().put("root", root).put("info", info)
        return json(j.toString())
    }

    private fun apiModules(): Triple<Int, String, ByteArray> {
        val ls = Shell.cmd("ls /data/adb/modules 2>/dev/null").exec()
        val arr = JSONArray()
        for (m in ls.out) {
            val p = Shell.cmd("cat /data/adb/modules/$m/module.prop 2>/dev/null").exec()
            var name = m
            var ver = ""
            for (l in p.out) {
                if (l.startsWith("name=")) name = l.substringAfter("name=")
                if (l.startsWith("version=")) ver = l.substringAfter("version=")
            }
            val enabled = Shell.cmd("[ -f /data/adb/modules/$m/disable ] && echo off || echo on").exec().out.joinToString("") == "on"
            arr.put(JSONObject().put("id", m).put("name", name).put("version", ver).put("enabled", enabled))
        }
        return json("""{"list":${arr.toString()}}""")
    }

    private fun apiModuleAction(body: String): Triple<Int, String, ByteArray> {
        val o = try { JSONObject(body) } catch (_: Exception) { return json("""{"error":"bad json"}""") }
        val id = o.optString("id")
        val act = o.optString("action")
        if (id.isBlank() || id.contains("/") || id.contains("..")) return json("""{"error":"bad id"}""")
        val dir = "/data/adb/modules/$id"
        val r = when (act) {
            "enable" -> Shell.cmd("rm -f '$dir/disable'").exec()
            "disable" -> Shell.cmd("touch '$dir/disable'").exec()
            "remove" -> Shell.cmd("rm -rf '$dir'").exec()
            "exec" -> Shell.cmd("sh '$dir/action.sh' 2>&1").exec()
            else -> return json("""{"error":"unknown action"}""")
        }
        val j = JSONObject()
            .put("out", r.out.joinToString("\n"))
            .put("err", r.err.joinToString("\n"))
            .put("code", r.code)
        return json(j.toString())
    }

    private fun apiNativeGet(): Triple<Int, String, ByteArray> {
        val j = JSONObject()
            .put("su", Natives.isSuEnabled())
            .put("selinux_hide", Natives.isSelinuxHideEnabled())
            .put("kernel_umount", Natives.isKernelUmountEnabled())
            .put("umount_default", Natives.isDefaultUmountModules())
        return json(j.toString())
    }

    private fun apiNativeSet(body: String): Triple<Int, String, ByteArray> {
        val o = try { JSONObject(body) } catch (_: Exception) { return json("{\"error\":\"bad json\"}".toByteArray()) }
        val key = o.optString("key")
        val v = o.optBoolean("value", false)
        val ok = when (key) {
            "su" -> Natives.setSuEnabled(v)
            "selinux_hide" -> Natives.setSelinuxHideEnabled(v) != 0
            "kernel_umount" -> Natives.setKernelUmountEnabled(v)
            "umount_default" -> Natives.setDefaultUmountModules(v)
            else -> return json("{\"error\":\"unknown key\"}".toByteArray())
        }
        return json("{\"ok\":$ok,\"key\":\"$key\",\"value\":$v}")
    }

    private fun apiReboot(): Triple<Int, String, ByteArray> {
        Shell.cmd("reboot").exec()
        return json("{\"ok\":true}")
    }

    private fun apiApps(): Triple<Int, String, ByteArray> {
        val arr = JSONArray()
        val pm = packageManager
        val pkgs = pm.getInstalledPackages(PackageManager.GET_META_DATA)
        for (pi in pkgs) {
            val pkg = pi.packageName
            if (pkg == packageName) continue
            val ai = pi.applicationInfo ?: continue
            val label = try { ai.loadLabel(pm).toString() } catch (_: Exception) { pkg }
            val prof = Natives.getAppProfile(pkg, ai.uid)
            arr.put(
                JSONObject()
                    .put("label", label)
                    .put("pkg", pkg)
                    .put("uid", ai.uid)
                    .put("su", prof.allowSu)
            )
        }
        return json("""{"apps":${arr.toString()}}""")
    }

    private fun apiIcon(query: String): Triple<Int, String, ByteArray> {
        val params = query.split("&").mapNotNull {
            val kv = it.split("=", limit = 2)
            if (kv.size == 2) kv[0] to kv[1] else null
        }.toMap()
        val pkg = params["pkg"] ?: return Triple(400, "application/json", "{\"error\":\"no pkg\"}".toByteArray())
        if (params["token"] != token) return Triple(401, "application/json", "{\"error\":\"unauthorized\"}".toByteArray())
        return try {
            val ai = packageManager.getApplicationInfo(pkg, 0)
            val d = packageManager.getApplicationIcon(ai)
            val bmp = Bitmap.createBitmap(108, 108, Bitmap.Config.ARGB_8888)
            val c = Canvas(bmp)
            d.setBounds(0, 0, 108, 108)
            d.draw(c)
            val bo = ByteArrayOutputStream()
            bmp.compress(Bitmap.CompressFormat.PNG, 90, bo)
            Triple(200, "image/png", bo.toByteArray())
        } catch (_: Exception) {
            Triple(404, "application/json", "{\"error\":\"not found\"}".toByteArray())
        }
    }

    private fun apiApp(body: String): Triple<Int, String, ByteArray> {
        val o = try { JSONObject(body) } catch (_: Exception) { return json("""{"error":"bad json"}""") }
        val pkg = o.optString("pkg")
        val su = o.optBoolean("su", false)
        if (pkg.isBlank()) return json("""{"error":"no pkg"}""")
        val uid = packageManager.getPackageUid(pkg, 0)
        val p = Natives.getAppProfile(pkg, uid)
        val np = p.copy(allowSu = su, rootUseDefault = true, nonRootUseDefault = true)
        val ok = Natives.setAppProfile(np)
        return json("""{"ok":$ok,"pkg":"$pkg","su":$su}""")
    }

    private fun apiExec(body: String): Triple<Int, String, ByteArray> {
        val cmd = try { JSONObject(body).optString("cmd") } catch (_: Exception) { "" }
        if (cmd.isBlank()) return json("""{"error":"empty"}""")
        val r = Shell.cmd(cmd).exec()
        val j = JSONObject()
            .put("out", r.out.joinToString("\n"))
            .put("err", r.err.joinToString("\n"))
            .put("code", r.code)
        return json(j.toString())
    }
}
